"""strata-distill CLI -- fine-tune local models from Strata training data."""

import argparse
import json
import sys
import tempfile
import urllib.request
import urllib.error
from pathlib import Path


# ---------------------------------------------------------------------------
# Default extraction system prompt -- used when exporting training data and
# when evaluating via Ollama (the model's system message).
# ---------------------------------------------------------------------------
_DEFAULT_SYSTEM_PROMPT = (
    "You are a knowledge extraction assistant. Extract structured knowledge "
    "entries from coding session transcripts. Output valid JSON matching this "
    'schema: {"entries": [{"type": "decision|solution|error_fix|pattern|procedure", '
    '"summary": "<120 chars>", "details": "<string>", "tags": ["<string>"], '
    '"relatedFiles": ["<string>"]}]}. Maximum 10 entries.'
)


def _find_config(explicit_path: str | None) -> Path:
    """Locate finetune_config.yaml: explicit path > package default."""
    if explicit_path:
        p = Path(explicit_path)
        if not p.exists():
            print(f"Error: Config not found: {p}", file=sys.stderr)
            sys.exit(1)
        return p

    # Fall back to the config bundled with the package
    default = Path(__file__).parent / "finetune_config.yaml"
    if default.exists():
        return default

    print(
        "Error: No finetune_config.yaml found. Pass --config explicitly.",
        file=sys.stderr,
    )
    sys.exit(1)


def cmd_start(args: argparse.Namespace) -> None:
    """Launch QLoRA fine-tuning.

    Pipeline: find DB -> export JSONL -> load config -> train -> export GGUF -> evaluate.
    """
    try:
        from .train import TrainConfig, load_config, train
    except ImportError as e:
        print(f"Error: {e}", file=sys.stderr)
        print("Install training dependencies: pip install -e '.[distill]'  (or 'strata-memory[distill]' once on PyPI)", file=sys.stderr)
        sys.exit(1)

    from .data import find_strata_db, load_training_pairs, export_jsonl

    # 1. Find the Strata database
    try:
        db_path = find_strata_db(args.db)
    except FileNotFoundError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Database: {db_path}")

    # 2. Export training data to a temp JSONL file
    task = args.task
    pairs = load_training_pairs(db_path, task_type=task, min_quality=0.7)
    if not pairs:
        print(f"No {task} training pairs found (min_quality=0.7).", file=sys.stderr)
        print("Accumulate more training data by using Strata with GEMINI_API_KEY set.")
        sys.exit(1)

    print(f"Found {len(pairs)} {task} training pairs")

    # Hold out 10% for evaluation (minimum 1)
    holdout_count = max(1, len(pairs) // 10)
    train_pairs = pairs[:-holdout_count]
    eval_pairs = pairs[-holdout_count:]

    with tempfile.TemporaryDirectory(prefix="strata-distill-") as tmpdir:
        train_jsonl = Path(tmpdir) / f"{task}-train.jsonl"
        eval_jsonl = Path(tmpdir) / f"{task}-eval.jsonl"

        export_jsonl(train_pairs, train_jsonl, system_prompt=_DEFAULT_SYSTEM_PROMPT)
        export_jsonl(eval_pairs, eval_jsonl, system_prompt=_DEFAULT_SYSTEM_PROMPT)
        print(f"Exported {len(train_pairs)} train + {len(eval_pairs)} eval examples")

        # 3. Load config
        config_path = _find_config(args.config)
        config = load_config(config_path)
        print(f"Config: {config_path}")
        print(f"  Model: {config.base_model}, LoRA rank: {config.lora_rank}")
        print(f"  Epochs: {config.epochs}, LR: {config.learning_rate}")

        # 4. Train
        try:
            result = train(config, train_jsonl)
        except (ImportError, RuntimeError) as e:
            print(f"Training failed: {e}", file=sys.stderr)
            sys.exit(1)

        print(f"\nTraining complete:")
        print(f"  Loss: {result.train_loss:.4f}")
        print(f"  Time: {result.train_time_seconds:.0f}s")
        print(f"  Model: {result.model_path}")

        # 5. Export GGUF
        try:
            from .export import export_gguf, register_ollama
        except ImportError as e:
            print(f"Error importing export module: {e}", file=sys.stderr)
            sys.exit(1)

        try:
            export_result = export_gguf(
                result.model_path,
                quantization=config.output_quantization,
            )
        except (ImportError, RuntimeError) as e:
            print(f"GGUF export failed: {e}", file=sys.stderr)
            sys.exit(1)

        print(f"\nGGUF exported:")
        print(f"  File: {export_result.gguf_path}")
        print(f"  Size: {export_result.size_bytes / 1024 / 1024:.1f} MB")

        # 6. Evaluate on held-out split
        _run_evaluation_on_holdout(eval_pairs, task)

        # 7. Print activation instructions
        print("\n" + "=" * 60)
        print("NEXT STEPS")
        print("=" * 60)
        if export_result.modelfile_path:
            model_name = f"strata-{task}-7b"
            print(f"1. Register with Ollama:")
            print(f"   ollama create {model_name} -f {export_result.modelfile_path}")
            print(f"2. Activate in Strata:")
            print(f"   strata distill activate")
            print(f"3. Evaluate:")
            print(f"   strata-distill eval --model {model_name}")


def _run_evaluation_on_holdout(eval_pairs: list, task: str) -> None:
    """Run the frozen eval on held-out pairs (best-effort, non-fatal)."""
    try:
        from .eval import evaluate_extraction

        test_cases = []
        model_outputs = []

        for pair in eval_pairs:
            test_cases.append({
                "id": f"holdout-{len(test_cases)}",
                "input": pair.input_text,
                "expected": json.loads(pair.output_json),
            })
            # Use the ground truth as the "model output" to establish ceiling
            model_outputs.append(pair.output_json)

        if task == "extraction" and test_cases:
            summary = evaluate_extraction(test_cases, model_outputs)
            print(f"\nHeld-out eval (ceiling -- ground truth as output):")
            print(f"  F1: {summary.mean_f1:.3f}")
            print(f"  JSON validity: {summary.json_validity_rate:.1%}")
    except Exception:
        # Evaluation is informational, never block the pipeline
        pass


def cmd_eval(args: argparse.Namespace) -> None:
    """Run evaluation against held-out test set.

    Supports two model sources:
    - Ollama model name (calls localhost:11434 API)
    - Path to test data JSONL with ground truth
    """
    from .eval import evaluate_extraction, load_test_cases

    # Load test data
    test_data_path = args.test_data
    if not test_data_path:
        # Try default location
        default_testdata = Path(__file__).parent / "testdata" / "extraction_test.jsonl"
        if default_testdata.exists():
            test_data_path = str(default_testdata)
        else:
            print(
                "Error: No test data specified. Pass --test-data PATH or place "
                "test cases in strata/distill/testdata/extraction_test.jsonl",
                file=sys.stderr,
            )
            sys.exit(1)

    try:
        test_cases = load_test_cases(test_data_path)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error loading test data: {e}", file=sys.stderr)
        sys.exit(1)

    if not test_cases:
        print("Error: No test cases found in file.", file=sys.stderr)
        sys.exit(1)

    print(f"Loaded {len(test_cases)} test cases from {test_data_path}")

    model = args.model
    if not model:
        print("Error: --model is required. Examples:", file=sys.stderr)
        print("  strata-distill eval --model strata-extraction-7b", file=sys.stderr)
        print("  strata-distill eval --model gemini-baseline", file=sys.stderr)
        sys.exit(1)

    # Generate model outputs
    print(f"Running inference with model: {model}")
    model_outputs = []

    for i, case in enumerate(test_cases):
        sys.stdout.write(f"\r  Processing {i + 1}/{len(test_cases)}...")
        sys.stdout.flush()

        output = _query_model(model, case["input"])
        model_outputs.append(output)

    print()  # newline after progress

    # Score
    summary = evaluate_extraction(test_cases, model_outputs)

    # Print results
    print("\n" + "=" * 60)
    print(f"EVALUATION RESULTS: {model}")
    print("=" * 60)
    print(f"  Test cases:        {summary.total_cases}")
    print(f"  Mean F1:           {summary.mean_f1:.3f}")
    print(f"  Mean Precision:    {summary.mean_precision:.3f}")
    print(f"  Mean Recall:       {summary.mean_recall:.3f}")
    print(f"  JSON validity:     {summary.json_validity_rate:.1%}")
    print(f"  Entry count acc:   {summary.entry_count_accuracy:.1%}")

    # Per-case breakdown for low scores
    low_scorers = [r for r in summary.results if r.f1 < 0.5]
    if low_scorers:
        print(f"\n  Low-scoring cases ({len(low_scorers)}):")
        for r in low_scorers[:5]:
            print(f"    {r.test_id}: F1={r.f1:.2f} P={r.precision:.2f} R={r.recall:.2f}")

    # Exit with non-zero if below threshold
    if summary.mean_f1 < 0.5:
        print(f"\n  WARN: F1 {summary.mean_f1:.3f} is below 0.5 threshold")
        sys.exit(1)


def _query_model(model: str, input_text: str) -> str:
    """Query a model for extraction output.

    For Ollama models, calls the local HTTP API at localhost:11434.
    Returns the raw model output string.
    """
    # Check if the model looks like an Ollama model name (not a file path)
    model_path = Path(model)
    if model_path.exists() and model_path.suffix == ".gguf":
        print(
            f"\n  GGUF direct inference not supported. Register with Ollama first:\n"
            f"    ollama create my-model -f /path/to/Modelfile",
            file=sys.stderr,
        )
        return "{}"

    # Query Ollama API
    url = "http://localhost:11434/api/generate"
    payload = json.dumps({
        "model": model,
        "prompt": input_text,
        "system": _DEFAULT_SYSTEM_PROMPT,
        "stream": False,
        "options": {
            "temperature": 0.1,
            "num_predict": 2048,
        },
    }).encode("utf-8")

    req = urllib.request.Request(
        url,
        data=payload,
        headers={"Content-Type": "application/json"},
    )

    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            return data.get("response", "{}")
    except urllib.error.URLError as e:
        print(
            f"\n  Could not reach Ollama at {url}: {e}\n"
            "  Is Ollama running? Start with: ollama serve",
            file=sys.stderr,
        )
        return "{}"
    except Exception as e:
        print(f"\n  Ollama query failed: {e}", file=sys.stderr)
        return "{}"


def cmd_export(args: argparse.Namespace) -> None:
    """Export GGUF model from the most recent trained adapter."""
    try:
        from .export import export_gguf, find_latest_model, register_ollama
    except ImportError as e:
        print(f"Error: {e}", file=sys.stderr)
        print("Install dependencies: pip install -e '.[distill]'  (or 'strata-memory[distill]' once on PyPI)", file=sys.stderr)
        sys.exit(1)

    # Find model to export
    model_path_str = args.model_path
    if model_path_str:
        model_path = Path(model_path_str)
        if not model_path.exists():
            print(f"Error: Model path not found: {model_path}", file=sys.stderr)
            sys.exit(1)
    else:
        try:
            model_path = find_latest_model()
        except FileNotFoundError as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

    print(f"Exporting model: {model_path}")

    quantization = args.quantization or "Q4_K_M"
    output_dir = Path(args.output).expanduser() if args.output != "." else None

    try:
        result = export_gguf(model_path, output_dir=output_dir, quantization=quantization)
    except (ImportError, RuntimeError, FileNotFoundError) as e:
        print(f"Export failed: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"\nExport complete:")
    print(f"  GGUF: {result.gguf_path}")
    print(f"  Size: {result.size_bytes / 1024 / 1024:.1f} MB")
    print(f"  Quantization: {result.quantization}")

    # Optionally register with Ollama
    if not args.skip_ollama:
        if result.modelfile_path:
            model_name = args.ollama_name or "strata-extraction-7b"
            success = register_ollama(result.modelfile_path, model_name)
            if success:
                print(f"\nReady to use: ollama run {model_name}")
    else:
        print(f"\nTo register with Ollama manually:")
        if result.modelfile_path:
            print(f"  ollama create strata-extraction-7b -f {result.modelfile_path}")


def cmd_status(args: argparse.Namespace) -> None:
    """Show training data stats (Python-side, reads DB directly)."""
    from .data import find_strata_db, get_stats

    try:
        db_path = find_strata_db(args.db)
    except FileNotFoundError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    stats = get_stats(db_path)
    extraction = stats.get("extraction", 0)
    summarization = stats.get("summarization", 0)

    print(f"Training data in {db_path}:")
    print(f"  Extraction:      {extraction} pairs")
    print(f"  Summarization:   {summarization} pairs")

    # Readiness thresholds
    threshold = 1000
    print()
    if extraction >= threshold:
        print(f"  Extraction:    READY (>= {threshold} pairs)")
    else:
        remaining = threshold - extraction
        print(f"  Extraction:    {remaining} more pairs needed (target: {threshold})")

    if summarization >= threshold:
        print(f"  Summarization: READY (>= {threshold} pairs)")
    else:
        remaining = threshold - summarization
        print(f"  Summarization: {remaining} more pairs needed (target: {threshold})")

    # Check for existing models
    models_dir = Path("~/.strata/models").expanduser()
    if models_dir.exists():
        models = [d for d in models_dir.iterdir() if d.is_dir() and d.name.startswith("strata-")]
        if models:
            print(f"\nTrained models in {models_dir}:")
            for m in sorted(models, key=lambda p: p.stat().st_mtime, reverse=True):
                print(f"  {m.name}")


def main() -> None:
    parser = argparse.ArgumentParser(
        prog="strata-distill",
        description="Fine-tune local models from Strata training data",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    # strata-distill start
    p_start = sub.add_parser("start", help="Launch QLoRA fine-tuning")
    p_start.add_argument(
        "--task", choices=["extraction", "summarization"], default="extraction"
    )
    p_start.add_argument("--db", type=str, help="Path to Strata database")
    p_start.add_argument("--config", type=str, help="Path to finetune_config.yaml")
    p_start.set_defaults(func=cmd_start)

    # strata-distill eval
    p_eval = sub.add_parser("eval", help="Evaluate model against test set")
    p_eval.add_argument("--model", type=str, help="Ollama model name or GGUF path")
    p_eval.add_argument("--test-data", type=str, help="Path to test cases JSONL")
    p_eval.set_defaults(func=cmd_eval)

    # strata-distill export
    p_export = sub.add_parser("export", help="Export GGUF model")
    p_export.add_argument("--output", type=str, default=".", help="Output directory")
    p_export.add_argument("--model-path", type=str, help="Path to trained adapter")
    p_export.add_argument("--quantization", type=str, help="GGUF quantization (default: Q4_K_M)")
    p_export.add_argument("--ollama-name", type=str, help="Ollama model name")
    p_export.add_argument(
        "--skip-ollama", action="store_true", help="Skip Ollama registration"
    )
    p_export.set_defaults(func=cmd_export)

    # strata-distill status
    p_status = sub.add_parser("status", help="Show training data statistics")
    p_status.add_argument("--db", type=str, help="Path to Strata database")
    p_status.set_defaults(func=cmd_status)

    args = parser.parse_args()
    args.func(args)


if __name__ == "__main__":
    main()
